# Surah Ta-Ha (chapter 20) — part 8: ayat 71-80 (IDs 2419-2428)
SURAH = 20

ENTRIES = {
2419: (
"فرعون نے کہا کیا تم نے میری اجازت کے بغیر اس پر ایمان لے آئے؟ یقیناً یہ تمہارا بڑا ہے جس نے تمہیں جادو سکھایا — پس میں تمہارے ہاتھ اور پاؤں خلاف سمت سے کاٹ دوں گا اور کھجور کے درختوں پر لٹکا دوں گا — اور تم جان لو گے کہ ہم میں سے کون زیادہ شدید عذاب دینے والا اور باقی رہنے والا ہے",
"""۱۔ فرعون کا غضب — جادوگروں نے ایمان لایا؛ کاٹنے کے اعلانات؛ استبداد۔
۲۔ ’’قَالَ آمَنتُمْ لَهُ قَبْلَ أَن آذَنَ لَكُمْ إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَافٍ وَلَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَا أَشَدُّ عَذَابًا وَأَبْقَىٰ‘‘ — فرعون نے کہا کیا تم نے میری اجازت کے بغیر اس پر ایمان لے آئے؟ یقیناً یہ تمہارا بڑا ہے جس نے تمہیں جادو سکھایا — پس میں تمہارے ہاتھ اور پاؤں خلاف سمت سے کاٹ دوں گا اور کھجور کے درختوں پر لٹکا دوں گا — اور تم جان لو گے کہ ہم میں سے کون زیادہ شدید عذاب دینے والا اور باقی رہنے والا ہے — یعنی فرعون نے کہا کیا تم نے میری اجازت سے پہلے ہی اس پر ایمان لائے یقیناً یہ تمہارا بڑا جادوگر ہے جس نے تمہیں جادو سکھایا پس میں تمہارے ہاتھ اور پاؤں خلاف سمت سے کاٹ دوں گا اور تمہیں کھجور کے درختوں پر سولی دوں گا اور تم جان لو گے ہم میں سے کس کا عذاب زیادہ سخت ہے اور کون باقی رہتا ہے۔
۳۔ عملی سبق: ظالم کے ساتھ سمجھوتہ نہ کرو؛ اللہ کے آگے جھک جاؤ؛ ظلم کی حکومت ختم ہوتی ہے۔"""
),
2420: (
"انہوں نے کہا ہم آپ کو اس پر ترجیح نہیں دیں گے جو ہمارے پاس کھلی نشانیوں سے اور اس ذات پر جس نے ہمیں پیدا کیا — پس آپ جو کرنا چاہتے ہیں کر ڈالو — آپ تو صرف اس دنیا کی زندگی میں جو کرنا ہے وہی کر سکتے ہیں",
"""۱۔ جادوگروں کا جواب — اللہ کی نشانیوں کے سامنے فرعون بے وقعت؛ ظالموں کا عذاب۔
۲۔ ’’قَالُوا لَن نُّؤْثِرَكَ عَلَىٰ مَا جَاءَنَا مِنَ الْبَيِّنَاتِ وَالَّذِي فَطَرَنَا فَاقْضِ مَا أَنتَ قَاضٍ إِنَّمَا تَقْضِي هَٰذِهِ الْحَيَاةَ الدُّنْيَا‘‘ — انہوں نے کہا ہم آپ کو اس پر ترجیح نہیں دیں گے جو ہمارے پاس کھلی نشانیوں سے اور اس ذات پر جس نے ہمیں پیدا کیا — پس آپ جو کرنا چاہتے ہیں کر ڈالو — آپ تو صرف اس دنیا کی زندگی میں جو کرنا ہے وہی کر سکتے ہیں — یعنی انہوں نے کہا ہم آپ کو ان پر ترجیح نہیں دیں گے جو ہمارے پاس کھلی نشانیوں سے آیا ہے اور اس ذات پر جس نے ہمیں پیدا کیا پس آپ وہ کر ڈالو جو آپ کرنا چاہتے ہیں آپ تو صرف اس دنیوی زندگی تک فیصلہ کر سکتے ہیں۔
۳۔ عملی سبق: اللہ کی راہ میں استقامت اختیار کرو؛ ظالموں کا ڈر نہ کرو؛ حق کی راہ پر رہو۔"""
),
2421: (
"بے شک ہم اپنے رب پر ایمان لائے تاکہ وہ ہمارے گناہ معاف کرے اور اس جادو کے لیے بھی جس پر آپ نے ہمیں مجبور کیا — اور اللہ بہتر ہے اور باقی رہنے والا ہے",
"""۱۔ جادوگروں کی دعا — گناہوں کی معافی؛ جبر کے گناہوں سے آزادی؛ اللہ کی بقا۔
۲۔ ’’إِنَّا آمَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَايَانَا وَمَا أَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِ وَاللَّهُ خَيْرٌ وَأَبْقَىٰ‘‘ — بے شک ہم اپنے رب پر ایمان لائے تاکہ وہ ہمارے گناہ معاف کرے اور اس جادو کے لیے بھی جس پر آپ نے ہمیں مجبور کیا — اور اللہ بہتر ہے اور باقی رہنے والا ہے — یعنی بے شک ہم اپنے رب پر ایمان لائے تاکہ وہ ہمارے گناہ معاف کرے اور جادو کے گناہ جو آپ نے ہم سے کروانا چاہا اور اللہ بہتر ہے اور باقی رہنے والا ہے۔
۳۔ عملی سبق: اپنے گناہوں کی توبہ کرو؛ اللہ کی مغفرت مانگو؛ اس پر بھروسہ رکھو۔"""
),
2422: (
"بے شک جو اپنے رب کے پاس مجرم ہو کر آئے گا اس کے لیے جہنم ہے جس میں نہ وہ مرے گا اور نہ زندہ رہے گا",
"""۱۔ مجرم کا انجام — جہنم؛ نہ موت؛ نہ زندگی؛ دائمی عذاب؛ اللہ کا انصاف۔
۲۔ ’’إِنَّهُ مَن يَأْتِ رَبَّهُ مُجْرِمًا فَإِنَّ لَهُ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ‘‘ — بے شک جو اپنے رب کے پاس مجرم ہو کر آئے گا اس کے لیے جہنم ہے جس میں نہ وہ مرے گا اور نہ زندہ رہے گا — یعنی بے شک جو اپنے رب کے پاس مجرم ہو کر آئے گا اس کے لیے جہنم ہے نہ اس میں وہ مرے گا اور نہ وہ زندہ رہے گا۔
۳۔ عملی سبق: گناہوں سے بچو؛ اللہ کے حضور نیک عمل کے ساتھ حاضر ہو؛ جہنم سے بچو۔"""
),
2423: (
"اور جو ایمان والا ہو کر نیک عمل کر کے اس کے پاس آئے تو ان کے لیے بلند درجے ہیں",
"""۱۔ مومن کا انجام — بلند درجے؛ اللہ کی رضا؛ جنت۔
۲۔ ’’وَمَن يَأْتِهِ مُؤْمِنًا قَدْ عَمِلَ الصَّالِحَاتِ فَأُولَٰئِكَ لَهُمُ الدَّرَجَاتُ الْعُلَىٰ‘‘ — اور جو ایمان والا ہو کر نیک عمل کر کے اس کے پاس آئے تو ان کے لیے بلند درجے ہیں — یعنی اور جو ایمان لا کر نیک عمل کرے ہوئے اس کے پاس آئے پس ان کے لیے بلند درجے ہیں۔
۳۔ عملی سبق: نیک عمل کرو؛ ایمان کے ساتھ اللہ کے حضور آؤ؛ جنت کی طلب کرو۔"""
),
2424: (
"اور ہمیشہ رہنے والے باغ ہیں جن کے نیچے نہریں بہتی ہیں — ان میں وہ ہمیشہ رہیں گے — اور یہ اس کا صلہ ہے جس نے خود کو پاک کیا",
"""۱۔ جنت — باغ؛ نہریں؛ دائمی زندگی؛ پاک ہونے والوں کا انعام۔
۲۔ ’’جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَٰلِكَ جَزَاءُ مَن تَزَكَّىٰ‘‘ — اور ہمیشہ رہنے والے باغ ہیں جن کے نیچے نہریں بہتی ہیں — ان میں وہ ہمیشہ رہیں گے — اور یہ اس کا صلہ ہے جس نے خود کو پاک کیا — یعنی جنت کے ہمیشہ رہنے والے باغ ہیں جن کے نیچے نہریں بہتی ہیں وہ ان میں ہمیشہ رہیں گے اور یہ اس کا صلہ ہے جس نے خود کو پاک کیا۔
۳۔ عملی سبق: خود کو شرک اور گناہ سے پاک کرو؛ اللہ کی رضا کے لیے نیک عمل کرو۔"""
),
2425: (
"اور یقیناً ہم نے موسیٰؑ کی طرف وحی کی کہ رات کے وقت میرے بندوں کو لے جاؤ — اور ان کے لیے سمندر میں خشک راستہ بناؤ — نہ تمہیں پکڑے جانے کا خطرہ ہو اور نہ تم ڈرو",
"""۱۔ اللہ کی وحی — موسیٰؑ کو بنی اسرائیل کو سمندر پار لینے کا حکم؛ خشک راستہ۔
۲۔ ’’وَلَقَدْ أَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَسْرِ بِعِبَادِي فَاضْرِبْ لَهُمْ طَرِيقًا فِي الْبَحْرِ يَبَسًا لَّا تَخَافُ دَرَكًا وَلَا تَخْشَىٰ‘‘ — اور یقیناً ہم نے موسیٰؑ کی طرف وحی کی کہ رات کے وقت میرے بندوں کو لے جاؤ — اور ان کے لیے سمندر میں خشک راستہ بناؤ — نہ تمہیں پکڑے جانے کا خطرہ ہو اور نہ تم ڈرو — یعنی اور ہم نے موسیٰؑ کی طرف وحی کی کہ رات کے وقت میرے بندوں کو لے جاؤ اور ان کے لیے سمندر میں خشک راستہ بنا دو نہ تمہیں پیچھے سے پکڑے جانے کا ڈر ہو اور نہ تم ڈرو۔
۳۔ عملی سبق: اللہ کی وحی پر اور ہدایت پر یقین رکھو؛ اس کے حکموں پر بھروسہ رکھو۔"""
),
2426: (
"پس فرعون اپنے لشکر سمیت ان کے پیچھے آیا اور انہیں دریا نے اپنی لپیٹ میں لے لیا جیسا کہ وہ لپیٹ میں لے لیتا ہے",
"""۱۔ فرعون کی پیچھا؛ سمندر نے اسے گھیر لیا؛ اللہ کا عذاب؛ ظالم کا انجام۔
۲۔ ’’فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ فَغَشِيَهُم مِّنَ الْيَمِّ مَا غَشِيَهُمْ‘‘ — پس فرعون اپنے لشکر سمیت ان کے پیچھے آیا اور انہیں دریا نے اپنی لپیٹ میں لے لیا جیسا کہ وہ لپیٹ میں لے لیتا ہے — یعنی پس فرعون اپنے لشکروں سمیت ان کے پیچھے آیا اور انہیں سمندر نے گھیر لیا جیسا کہ وہ گھیر لیتا ہے۔
۳۔ عملی سبق: اللہ کی طاقت کے آگے کوئی تدبیر کارگر نہیں؛ اس کے عذاب سے بچو۔"""
),
2427: (
"اور فرعون نے اپنی قوم کو گمراہ کیا اور انہیں ہدایت نہیں کی",
"""۱۔ فرعون نے اپنی قوم کو گمراہ کیا؛ اللہ کا غضب؛ ظالم کا انجام؛ قوم کی تباہی۔
۲۔ ’’وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَىٰ‘‘ — اور فرعون نے اپنی قوم کو گمراہ کیا اور انہیں ہدایت نہیں کی — یعنی اور فرعون نے اپنی قوم کو گمراہ کیا اور انہیں ہدایت نہیں دی۔
۳۔ عملی سبق: ظالم رہنما لوگوں کو گمراہ کرتے ہیں؛ عقل استعمال کرو؛ حق کی راہ چلو۔"""
),
2428: (
"اے بنی اسرائیل یقیناً ہم نے تمہیں تمہارے دشمن سے نجات دی اور ہم نے تم سے طور کے دائیں جانب کا وعدہ کیا اور تم پر من و سلویٰ نازل کیا",
"""۱۔ اللہ کی نعمتیں — دشمن سے نجات؛ طور کا وعدہ؛ من و سلویٰ؛ اللہ کی کرم۔
۲۔ ’’يَا بَنِي إِسْرَائِيلَ قَدْ أَنجَيْنَاكُم مِّنْ عَدُوِّكُمْ وَوَاعَدْنَاكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ‘‘ — اے بنی اسرائیل یقیناً ہم نے تمہیں تمہارے دشمن سے نجات دی اور ہم نے تم سے طور کے دائیں جانب کا وعدہ کیا اور تم پر من و سلویٰ نازل کیا — یعنی اے بنی اسرائیل ہم نے تمہیں تمہارے دشمن سے نجات دی اور ہم نے تم سے طور کے دائیں جانب کا وعدہ کیا اور تم پر من و سلویٰ نازل کیا۔
۳۔ عملی سبق: اللہ کی نعمتوں پر شکر کرو؛ اس کا عہد یاد رکھو۔"""
),
}
